import unittest
from candidate import largest_divisor

class TestLargestDivisor(unittest.TestCase):
    def test_largest_divisor_normalcase(self):
        self.assertEqual(largest_divisor(15), 5)

    def test_largest_divisor_boundary_1(self):
        self.assertEqual(largest_divisor(1), 1)

    def test_largest_divisor_boundary_2(self):
        self.assertEqual(largest_divisor(2), 2)

    def test_largest_divisor_empty_input(self):
        self.assertIsNone(largest_divisor(0))

    def test_largest_divisor_none_value(self):
        self.assertIsNone(largest_divisor(None))

    def test_largest_divisor_type_error(self):
        self.assertRaises(TypeError, largest_divisor, 1.5)

    def test_largest_divisor_edgecase_1(self):
        self.assertEqual(largest_divisor(4), 2)

    def test_largest_divisor_edgecase_2(self):
        self.assertEqual(largest_divisor(6), 3)
